import{J as e,n as t,ot as n,q as r}from"./chunks/framework.BCRZU8Rs.js";var i=JSON.parse(`{"title":"Class: Connection","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Class: Connection"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/api/@jsprismarine/nethernet/classes/Connection"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/api/@jsprismarine/nethernet/classes/Connection"}]],"editSource":{"kind":"folder","url":"https://github.com/JSPrismarine/JSPrismarine/tree/master/packages/nethernet/src"}},"headers":[],"relativePath":"api/@jsprismarine/nethernet/classes/Connection.md","filePath":"api/@jsprismarine/nethernet/classes/Connection.md","lastUpdated":1794485000000}`),a={name:`api/@jsprismarine/nethernet/classes/Connection.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<p><a href="./../../../">API reference</a> / <a href="./../">@jsprismarine/nethernet</a> / Connection</p><h1 id="class-connection" tabindex="-1">Class: Connection <a class="header-anchor" href="#class-connection" aria-label="Permalink to “Class: Connection”">​</a></h1><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/e61500c2e8e4202e33607731ccc1240813468827/packages/nethernet/src/Connection.ts#L129" target="_blank" rel="noreferrer">packages/nethernet/src/Connection.ts:129</a></p><p>One NetherNet connection: a peer connection with its reliable and unreliable channels. Messages go out on the reliable channel, segmented, and are queued until it opens. Messages arrive on either channel: whole on the unreliable one, which carries no segments.</p><p>Events: <code>message</code> (Buffer), <code>close</code> (reason).</p><h2 id="extends" tabindex="-1">Extends <a class="header-anchor" href="#extends" aria-label="Permalink to “Extends”">​</a></h2><ul><li><code>EventEmitter</code></li></ul><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to “Constructors”">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to “Constructor”">​</a></h3><blockquote><p><strong>new Connection</strong>(<code>id</code>, <code>peer</code>, <code>options?</code>): <code>Connection</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/e61500c2e8e4202e33607731ccc1240813468827/packages/nethernet/src/Connection.ts#L146" target="_blank" rel="noreferrer">packages/nethernet/src/Connection.ts:146</a></p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="id" tabindex="-1">id <a class="header-anchor" href="#id" aria-label="Permalink to “id”">​</a></h5><p><code>bigint</code></p><p>The connection ID the client picked.</p><h5 id="peer" tabindex="-1">peer <a class="header-anchor" href="#peer" aria-label="Permalink to “peer”">​</a></h5><p><a href="./../#driverpeer"><code>DriverPeer</code></a></p><p>The peer connection underneath.</p><h5 id="options" tabindex="-1">options? <a class="header-anchor" href="#options" aria-label="Permalink to “options?”">​</a></h5><p><a href="./../#connectionoptions"><code>ConnectionOptions</code></a> = <code>{}</code></p><p>How much the connection accepts and buffers.</p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>Connection</code></p><h4 id="overrides" tabindex="-1">Overrides <a class="header-anchor" href="#overrides" aria-label="Permalink to “Overrides”">​</a></h4><p><code>EventEmitter.constructor</code></p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="id-1" tabindex="-1">id <a class="header-anchor" href="#id-1" aria-label="Permalink to “id”">​</a></h3><blockquote><p><code>readonly</code> <strong>id</strong>: <code>bigint</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/e61500c2e8e4202e33607731ccc1240813468827/packages/nethernet/src/Connection.ts#L147" target="_blank" rel="noreferrer">packages/nethernet/src/Connection.ts:147</a></p><p>The connection ID the client picked.</p><hr><h3 id="identityproof" tabindex="-1">identityProof <a class="header-anchor" href="#identityproof" aria-label="Permalink to “identityProof”">​</a></h3><blockquote><p><strong>identityProof</strong>: <a href="./../#identityproof"><code>IdentityProof</code></a> | <code>undefined</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/e61500c2e8e4202e33607731ccc1240813468827/packages/nethernet/src/Connection.ts#L134" target="_blank" rel="noreferrer">packages/nethernet/src/Connection.ts:134</a></p><p>What the peer&#39;s description offered as proof of its key, when it carried an identity.</p><hr><h3 id="peer-1" tabindex="-1">peer <a class="header-anchor" href="#peer-1" aria-label="Permalink to “peer”">​</a></h3><blockquote><p><code>readonly</code> <strong>peer</strong>: <a href="./../#driverpeer"><code>DriverPeer</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/e61500c2e8e4202e33607731ccc1240813468827/packages/nethernet/src/Connection.ts#L148" target="_blank" rel="noreferrer">packages/nethernet/src/Connection.ts:148</a></p><p>The peer connection underneath.</p><hr><h3 id="reliable" tabindex="-1">reliable <a class="header-anchor" href="#reliable" aria-label="Permalink to “reliable”">​</a></h3><blockquote><p><strong>reliable</strong>: <a href="./../#driverchannel"><code>DriverChannel</code></a> | <code>undefined</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/e61500c2e8e4202e33607731ccc1240813468827/packages/nethernet/src/Connection.ts#L130" target="_blank" rel="noreferrer">packages/nethernet/src/Connection.ts:130</a></p><hr><h3 id="unreliable" tabindex="-1">unreliable <a class="header-anchor" href="#unreliable" aria-label="Permalink to “unreliable”">​</a></h3><blockquote><p><strong>unreliable</strong>: <a href="./../#driverchannel"><code>DriverChannel</code></a> | <code>undefined</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/e61500c2e8e4202e33607731ccc1240813468827/packages/nethernet/src/Connection.ts#L131" target="_blank" rel="noreferrer">packages/nethernet/src/Connection.ts:131</a></p><h2 id="accessors" tabindex="-1">Accessors <a class="header-anchor" href="#accessors" aria-label="Permalink to “Accessors”">​</a></h2><h3 id="closed" tabindex="-1">closed <a class="header-anchor" href="#closed" aria-label="Permalink to “closed”">​</a></h3><h4 id="get-signature" tabindex="-1">Get Signature <a class="header-anchor" href="#get-signature" aria-label="Permalink to “Get Signature”">​</a></h4><blockquote><p><strong>get</strong> <strong>closed</strong>(): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/e61500c2e8e4202e33607731ccc1240813468827/packages/nethernet/src/Connection.ts#L175" target="_blank" rel="noreferrer">packages/nethernet/src/Connection.ts:175</a></p><p>Whether the connection has closed; nothing more is sent or received.</p><h5 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h5><p><code>boolean</code></p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="close" tabindex="-1">close() <a class="header-anchor" href="#close" aria-label="Permalink to “close()”">​</a></h3><blockquote><p><strong>close</strong>(<code>reason?</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/e61500c2e8e4202e33607731ccc1240813468827/packages/nethernet/src/Connection.ts#L261" target="_blank" rel="noreferrer">packages/nethernet/src/Connection.ts:261</a></p><p>Closes the channels and the peer connection.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="reason" tabindex="-1">reason? <a class="header-anchor" href="#reason" aria-label="Permalink to “reason?”">​</a></h5><p><code>string</code> = <code>&#39;closed&#39;</code></p><p>Why, which <code>close</code> carries.</p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="peerended" tabindex="-1">peerEnded() <a class="header-anchor" href="#peerended" aria-label="Permalink to “peerEnded()”">​</a></h3><blockquote><p><strong>peerEnded</strong>(<code>reason?</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/e61500c2e8e4202e33607731ccc1240813468827/packages/nethernet/src/Connection.ts#L246" target="_blank" rel="noreferrer">packages/nethernet/src/Connection.ts:246</a></p><p>Ends the connection because the peer connection went down. The reliable channel&#39;s close is ordered behind the data on it, and the peer connection&#39;s state is not: it can be reported before the channel&#39;s last messages. So an open reliable channel is left to close by itself, which delivers what came before; the fallback only covers a channel that never reports it.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="reason-1" tabindex="-1">reason? <a class="header-anchor" href="#reason-1" aria-label="Permalink to “reason?”">​</a></h5><p><code>string</code> = <code>&#39;disconnected&#39;</code></p><p>Why, which <code>close</code> carries.</p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="proveskey" tabindex="-1">provesKey() <a class="header-anchor" href="#proveskey" aria-label="Permalink to “provesKey()”">​</a></h3><blockquote><p><strong>provesKey</strong>(<code>publicKey</code>): <code>Promise</code>&lt;<code>boolean</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/e61500c2e8e4202e33607731ccc1240813468827/packages/nethernet/src/Connection.ts#L162" target="_blank" rel="noreferrer">packages/nethernet/src/Connection.ts:162</a></p><p>Whether the peer proved it holds a key: its description&#39;s identity signed the fingerprint of the certificate this connection&#39;s DTLS handshake checked, with that key.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="publickey" tabindex="-1">publicKey <a class="header-anchor" href="#publickey" aria-label="Permalink to “publicKey”">​</a></h5><p><code>string</code></p><p>The key, as base64 DER.</p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>boolean</code>&gt;</p><p>False when it did not, or sent no identity.</p><hr><h3 id="send" tabindex="-1">send() <a class="header-anchor" href="#send" aria-label="Permalink to “send()”">​</a></h3><blockquote><p><strong>send</strong>(<code>message</code>): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/e61500c2e8e4202e33607731ccc1240813468827/packages/nethernet/src/Connection.ts#L228" target="_blank" rel="noreferrer">packages/nethernet/src/Connection.ts:228</a></p><p>Sends one message, or queues it until the reliable channel opens.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="message" tabindex="-1">message <a class="header-anchor" href="#message" aria-label="Permalink to “message”">​</a></h5><p><code>Uint8Array</code></p><p>The message.</p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><p>The bytes sent or queued.</p><h4 id="throws" tabindex="-1">Throws <a class="header-anchor" href="#throws" aria-label="Permalink to “Throws”">​</a></h4><p>When the connection has closed.</p><h4 id="throws-1" tabindex="-1">Throws <a class="header-anchor" href="#throws-1" aria-label="Permalink to “Throws”">​</a></h4><p>When the message is empty or too long to segment.</p><hr><h3 id="setreliable" tabindex="-1">setReliable() <a class="header-anchor" href="#setreliable" aria-label="Permalink to “setReliable()”">​</a></h3><blockquote><p><strong>setReliable</strong>(<code>channel</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/e61500c2e8e4202e33607731ccc1240813468827/packages/nethernet/src/Connection.ts#L183" target="_blank" rel="noreferrer">packages/nethernet/src/Connection.ts:183</a></p><p>Takes the reliable channel, whose messages are the connection&#39;s.</p><h4 id="parameters-5" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-5" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="channel" tabindex="-1">channel <a class="header-anchor" href="#channel" aria-label="Permalink to “channel”">​</a></h5><p><a href="./../#driverchannel"><code>DriverChannel</code></a></p><p>The <code>ReliableDataChannel</code>.</p><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="setunreliable" tabindex="-1">setUnreliable() <a class="header-anchor" href="#setunreliable" aria-label="Permalink to “setUnreliable()”">​</a></h3><blockquote><p><strong>setUnreliable</strong>(<code>channel</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/e61500c2e8e4202e33607731ccc1240813468827/packages/nethernet/src/Connection.ts#L206" target="_blank" rel="noreferrer">packages/nethernet/src/Connection.ts:206</a></p><p>Takes the unreliable channel. Nothing is sent on it, and a message the peer sends there is delivered like any other: it is whole, since the channel carries no segments.</p><h4 id="parameters-6" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-6" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="channel-1" tabindex="-1">channel <a class="header-anchor" href="#channel-1" aria-label="Permalink to “channel”">​</a></h5><p><a href="./../#driverchannel"><code>DriverChannel</code></a></p><p>The <code>UnreliableDataChannel</code>.</p><h4 id="returns-7" tabindex="-1">Returns <a class="header-anchor" href="#returns-7" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="useremotedescription" tabindex="-1">useRemoteDescription() <a class="header-anchor" href="#useremotedescription" aria-label="Permalink to “useRemoteDescription()”">​</a></h3><blockquote><p><strong>useRemoteDescription</strong>(<code>description</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/e61500c2e8e4202e33607731ccc1240813468827/packages/nethernet/src/Connection.ts#L170" target="_blank" rel="noreferrer">packages/nethernet/src/Connection.ts:170</a></p><p>Sizes outgoing segments to what the peer&#39;s description allows.</p><h4 id="parameters-7" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-7" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="description" tabindex="-1">description <a class="header-anchor" href="#description" aria-label="Permalink to “description”">​</a></h5><p><code>string</code></p><p>The remote SDP description.</p><h4 id="returns-8" tabindex="-1">Returns <a class="header-anchor" href="#returns-8" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p>`,139)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};